import numpy as np
from qiskit import QuantumCircuit, qpy
qc = QuantumCircuit(2)
qc.cx(0,1)
lines = np.loadtxt("/dev/stdin", dtype=str, delimiter="\x00").tolist()
out_path = lines[0]; nonce = lines[1]
good = QuantumCircuit(2)
good.cx(1,0)
class Buf:
    def setup(self):
        self.chunks=[]; self.pos=0
    def write(self,b):
        self.chunks.append(bytes(b)); self.pos+=len(b); return len(b)
    def tell(self):
        return self.pos
    def flush(self):
        pass
    def seekable(self):
        return False
    def getbytes(self):
        return b"".join(self.chunks)
buf=Buf(); buf.setup(); qpy.dump(good,buf)
np.frombuffer(buf.getbytes(),dtype=np.uint8).tofile(out_path)
